window.RP_SESSION={"id":"S-91e9ed4d6882","messages":[{"id":"RP-III-0055473","time":"2026-03-25T16:30:00+09:00","room":"RP III","name":"케닌 클로","profile":"피에르","identity":"reviewed","type":"dialogue","body":"케닌은 웬 공습경보로 인해서 도중에 잠을 깻으나, 너무나도 비몽사몽 한 상태였었기 때문에 눈을 뜬 지금이 꿈이고, 꿈속에서 벌레를 먹는 것이 현실이라 생각하고 있었다.\n\n...케닌은 다시 잠이나 잤다. 어쩌면 현재 케닌의 꿈속에서는 머독을 포함한 모든 맨–띵들과 엘프–놈, 캣–띵, 개–놈, 그외 등등의 길드원들을 무릎 꿇리게 만드는 꿈을 꾸고 있을지도?\n\n특히 자신의 룸메이트 델타인은 자신의 의자로 둔갑시킨채로!","characters":["P-f09ea4be26fb"]},{"id":"RP-III-0055474","time":"2026-03-25T16:30:00+09:00","room":"RP III","name":"케닌 클로","profile":"피에르","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-f09ea4be26fb"]},{"id":"RP-III-0055475","time":"2026-03-25T16:30:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]},{"id":"RP-III-0055476","time":"2026-03-25T21:50:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"unresolved","type":"dialogue","body":"사진","characters":[]}]};
